"""Count metadata-only support for the frozen P-L2-002 comparison."""
from collections import defaultdict
from functools import lru_cache
from itertools import combinations
import json
from pathlib import Path
import re
import sys

sys.path.insert(0, str(Path.cwd()))
from vs import corpus, ivtff

HANDS = ('2', '3', '5')
EDITION = ('zl', 'it')


def folio(page_id):
    return re.match(r'f\d+', page_id).group()


def certain_words(page):
    return sum(not ivtff.uncertain(word) for line in page.lines if line.unit == 'P' for word in line.words)


def sample(pages, folio_order):
    by_edition = {edition: {page.id: page for page in pages[edition]} for edition in EDITION}
    for pid, zl in by_edition['zl'].items():
        it = by_edition['it'].get(pid)
        if it is None or zl.section != 'H' or zl.language != 'B' or str(zl.hand) not in HANDS:
            continue
        if (zl.section, zl.language, str(zl.hand)) != (it.section, it.language, str(it.hand)):
            continue
        lengths = [certain_words(zl), certain_words(it)]
        if min(lengths) >= 40 and zl.meta.get('Q'):
            yield {'id': pid, 'folio': folio(pid), 'hand': str(zl.hand), 'quire': zl.meta['Q'],
                   'order': folio_order[folio(pid)], 'lengths': lengths, 'bifolio': zl.meta.get('B')}


def pair_support(edges):
    incident = defaultdict(set)
    for left, right in edges:
        incident[left].add(right)
    assigned = {}

    def augment(left, visited):
        for right in sorted(incident[left] - visited):
            visited.add(right)
            if right not in assigned or augment(assigned[right], visited):
                assigned[right] = left
                return True
        return False

    for left in sorted(incident):
        augment(left, set())
    return len(assigned)


def quire_support(blocks):
    groups = tuple(sorted(blocks))

    @lru_cache(maxsize=None)
    def maximum(index, used):
        if index == len(groups):
            return 0
        best = maximum(index + 1, used)
        block = frozenset(groups[index])
        if block.isdisjoint(used):
            best = max(best, 1 + maximum(index + 1, used | block))
        return best

    return maximum(0, frozenset())


def support(pairs):
    folio_edges = {(a['folio'], b['folio']) for a, b, _ in pairs}
    blocks = {tuple(sorted({a['quire'], b['quire']})) for a, b, _ in pairs}
    return {'page_pairs': len(pairs), 'pages': sorted({p['id'] for a,b,_ in pairs for p in (a,b)}),
            'folio_pairs': sorted(folio_edges), 'folios': sorted({f for edge in folio_edges for f in edge}),
            'quire_blocks': [list(x) for x in sorted(blocks)], 'folio_disjoint_pairs': pair_support(folio_edges),
            'quire_disjoint_pairs': quire_support(blocks)}


def enumerate_pairs(test, train, rule, contrast):
    a_hand, b_hand = contrast
    left = [p for p in test if p['hand'] == a_hand]
    right = [p for p in test if p['hand'] == b_hand]
    for a in left:
        for b in right:
            distance = abs(a['order'] - b['order'])
            if not 0 < distance <= rule['max_folio_distance']:
                continue
            length_ratio = max(max(x, y)/min(x, y) for x, y in zip(a['lengths'], b['lengths']))
            if length_ratio > rule['max_length_ratio']:
                continue
            eligible = [r for r in train if r['quire'] not in (a['quire'], b['quire'])
                        and r['folio'] not in (a['folio'], b['folio'])]
            fit = {hand: len({r['folio'] for r in eligible if r['hand'] == hand}) for hand in contrast}
            yield a, b, fit


def main():
    plan = json.loads(Path(sys.argv[1]).read_text())
    all_folios = list(dict.fromkeys(folio(page.id) for page in corpus.pages('zl')))
    folio_order = {name: i for i, name in enumerate(all_folios)}
    partitions = {edition: corpus.split_pages('practice', edition) for edition in EDITION}
    train = list(sample({edition: partitions[edition][0] for edition in EDITION}, folio_order))
    test = list(sample({edition: partitions[edition][1] for edition in EDITION}, folio_order))
    rows = {}
    for name, rule in plan['matches'].items():
        results = {}
        for contrast in combinations(HANDS, 2):
            eligible = list(enumerate_pairs(test, train, rule, contrast))
            trainable = [(a,b,fit) for a,b,fit in eligible if min(fit.values()) >= 2]
            same_quire = [(a,b,fit) for a,b,fit in trainable if a['quire'] == b['quire']]
            results['-'.join(contrast)] = {'raw': support(eligible), 'trainable': support(trainable),
                'trainable_same_quire': support(same_quire),
                'pair_details': [{'pages':[a['id'], b['id']], 'quires':[a['quire'], b['quire']],
                                  'training_folios':fit} for a,b,fit in eligible]}
        rows[name] = results
    proximity = {}
    for hand in ('2', '5'):
        distance, left, right = min((abs(a['order'] - b['order']), a['folio'], b['folio'])
                                    for a in train + test for b in train + test
                                    if a['hand'] == '3' and b['hand'] == hand)
        proximity['3-' + hand] = {'distance': distance, 'folios': [left, right]}
    print(json.dumps({'public_practice_training':train,'public_practice_evaluation':test,
                      'minimum_distances_to_hand_3':proximity,'matches':rows}, indent=2))


if __name__ == '__main__':
    main()

